    // ---- T0.4b: the three holes, complete against Roslyn's own view of the running runtime ----

    private static bool HasFloatElement(ITypeSymbol t) => t switch
    {
        IPointerTypeSymbol p => HasFloatElement(p.PointedAtType),
        IArrayTypeSymbol a => HasFloatElement(a.ElementType),
        INamedTypeSymbol n => n.SpecialType is SpecialType.System_Double or SpecialType.System_Single || n.Name == "Half" || n.TypeArguments.Any(HasFloatElement),
        _ => false,
    };

    private static IEnumerable<INamedTypeSymbol> IsaTypes()
    {
        var root = s_compilation.Value.GlobalNamespace;
        foreach (var name in new[] { "X86", "Arm", "Wasm" })
        {
            var ns = root.GetNamespaceMembers().Single(n => n.Name == "System").GetNamespaceMembers().Single(n => n.Name == "Runtime")
                .GetNamespaceMembers().Single(n => n.Name == "Intrinsics").GetNamespaceMembers().Single(n => n.Name == name);
            var stack = new Stack<INamedTypeSymbol>(ns.GetTypeMembers().Where(t => t.DeclaredAccessibility == Accessibility.Public));
            while (stack.Count > 0)
            {
                var t = stack.Pop();
                yield return t;
                foreach (var nested in t.GetTypeMembers().Where(n => n.DeclaredAccessibility == Accessibility.Public)) stack.Push(nested);
            }
        }
    }

    [TestMethod]
    public void EveryFusedMultiplyAddIntrinsicIsBanned()
    {
        var expectedIds = new List<string>();
        var missing = new List<string>();
        var wronglyBanned = new List<string>();
        var types = IsaTypes().ToList();
        foreach (var type in types)
        {
            bool isFma = type.ToDisplayString().StartsWith("System.Runtime.Intrinsics.X86.Fma", StringComparison.Ordinal);
            if (isFma && !s_file.Value.Entries.Contains(type.GetDocumentationCommentId()!)) missing.Add(type.GetDocumentationCommentId()!);
            foreach (var m in type.GetMembers().OfType<IMethodSymbol>().Where(m => m.DeclaredAccessibility == Accessibility.Public && m.IsStatic && m.MethodKind == MethodKind.Ordinary))
            {
                bool expected = isFma
                    || m.Name.StartsWith("FusedMultiply", StringComparison.Ordinal)
                    || ((m.Name.Contains("MultiplyAdd") || m.Name.Contains("MultiplySubtract")) && m.Parameters.Any(p => HasFloatElement(p.Type)));
                var id = m.GetDocumentationCommentId()!;
                bool present = s_file.Value.Entries.Contains(id);
                if (expected) expectedIds.Add(id);
                if (expected && !present) missing.Add(id);
                if (!expected && present) wronglyBanned.Add(id);
            }
        }

        // not vacuous: the families the card names are there to be found
        foreach (var family in new[] { "X86.Fma.MultiplyAdd(", "X86.Fma.MultiplyAddNegated", "X86.Fma.MultiplySubtractAdd", "Arm.AdvSimd.FusedMultiplyAdd(", "Arm.AdvSimd.FusedMultiplySubtract(",
                                     "Arm.AdvSimd.Arm64.FusedMultiplyAdd(", "Arm.Sve.TrigonometricMultiplyAddCoefficient(", "X86.Avx512F.FusedMultiplyAdd(", "X86.Avx10v1.FusedMultiplyAddScalar(", "Arm.Sve.FusedMultiplyAdd(" })
            Assert.IsTrue(expectedIds.Any(id => id.Contains("System.Runtime.Intrinsics." + family)) || s_file.Value.Entries.Any(e => e.Contains("System.Runtime.Intrinsics." + family)),
                $"{family} was not found in the runtime: has the API moved?");
        Assert.IsGreaterThan(100, expectedIds.Count);

        CollectionAssert.AreEqual(Array.Empty<string>(), missing, "not banned, but should be: regenerate BannedSymbols.txt");
        CollectionAssert.AreEqual(Array.Empty<string>(), wronglyBanned, "banned, but it is an exact (integer) multiply-add");
    }

    [TestMethod]
    public void TheIntegerMultiplyAddAndTheOtherNeighboursOfTheFmaFamilyStayAllowed()
    {
        var entries = s_file.Value.Entries;
        Assert.IsFalse(entries.Any(e => e.Contains("MultiplyAddAdjacent")), "MultiplyAddAdjacent is an exact integer operation");
        Assert.IsFalse(entries.Any(e => e.StartsWith("M:System.Runtime.Intrinsics.X86.Sse2.Add(") || e.StartsWith("M:System.Runtime.Intrinsics.Arm.AdvSimd.Add(")), "plain Add stays allowed");
        Assert.IsFalse(entries.Any(e => e.StartsWith("M:System.Runtime.Intrinsics.Vector128.ConditionalSelect") || e.StartsWith("M:System.Runtime.Intrinsics.Vector128.Add(")));
    }

    [TestMethod]
    public void EveryConvertToOverloadWithAFloatingPointParameterIsBanned()
    {
        string[] integerTargets = ["ToSByte", "ToByte", "ToInt16", "ToUInt16", "ToInt32", "ToUInt32", "ToInt64", "ToUInt64", "ToChar", "ToDecimal", "ToBoolean"];
        var missing = new List<string>();
        var wronglyBanned = new List<string>();
        int expectedCount = 0;
        foreach (var m in PublicStaticMethods("System.Convert"))
        {
            bool floatParam = m.Parameters.Any(p => HasFloatElement(p.Type));
            bool floatOrStringResult = HasFloatElement(m.ReturnType) || m.ReturnType.SpecialType == SpecialType.System_String;
            bool expected = (m.Name.StartsWith("To", StringComparison.Ordinal) && floatParam && !floatOrStringResult)
                || m.Name == "ChangeType"
                || (integerTargets.Contains(m.Name) && m.Parameters.Length >= 1 && m.Parameters[0].Type.SpecialType == SpecialType.System_Object);
            var id = m.GetDocumentationCommentId()!;
            bool present = s_file.Value.Entries.Contains(id);
            if (expected) expectedCount++;
            if (expected && !present) missing.Add(id);
            if (!expected && present) wronglyBanned.Add(id);
        }
        Assert.IsGreaterThanOrEqualTo(22, expectedCount, "ToSByte..ToBoolean have a double and a float overload each; the object ones and ChangeType come on top");

        var convertible = s_compilation.Value.GetTypeByMetadataName("System.IConvertible")!;
        foreach (var m in convertible.GetMembers().OfType<IMethodSymbol>().Where(m => integerTargets.Contains(m.Name)))
            if (!s_file.Value.Entries.Contains(m.GetDocumentationCommentId()!)) missing.Add(m.GetDocumentationCommentId()!);

        CollectionAssert.AreEqual(Array.Empty<string>(), missing, "not banned, but should be: regenerate BannedSymbols.txt");
        CollectionAssert.AreEqual(Array.Empty<string>(), wronglyBanned, "banned, but allowed (returns a floating-point type or a string, or takes no float)");
    }

    [TestMethod]
    public void TheConvertOverloadsThatDoNotConvertAFloatToAnIntegerStayAllowed()
    {
        var entries = s_file.Value.Entries;
        foreach (var id in new[] { "M:System.Convert.ToDouble(System.Int32)", "M:System.Convert.ToDouble(System.Single)", "M:System.Convert.ToDouble(System.Double)", "M:System.Convert.ToSingle(System.Double)",
                                   "M:System.Convert.ToInt32(System.String)", "M:System.Convert.ToInt32(System.Int64)", "M:System.Convert.ToInt32(System.Boolean)", "M:System.Convert.ToString(System.Double)" })
            Assert.IsFalse(entries.Contains(id), id + " must stay allowed");
        Assert.IsTrue(entries.Contains("M:System.Convert.ToInt32(System.Double)"));
        Assert.IsTrue(entries.Contains("M:System.Convert.ToInt32(System.Single)"));
    }

    [TestMethod]
    public void EveryIntegerCreateTruncatingSaturatingAndCheckedIsBanned()
    {
        string[] createNames = ["CreateChecked", "CreateSaturating", "CreateTruncating"];
        string[] integerTypes = ["System.SByte", "System.Byte", "System.Int16", "System.UInt16", "System.Int32", "System.UInt32", "System.Int64", "System.UInt64", "System.IntPtr", "System.UIntPtr",
                                 "System.Int128", "System.UInt128", "System.Numerics.BigInteger"];
        var missing = new List<string>();
        int count = 0;
        foreach (var type in integerTypes.Append("System.Numerics.INumberBase`1"))
            foreach (var m in s_compilation.Value.GetTypeByMetadataName(type)!.GetMembers().OfType<IMethodSymbol>()
                         .Where(m => m.DeclaredAccessibility == Accessibility.Public && m.MethodKind == MethodKind.Ordinary && createNames.Contains(m.Name)))
            {
                count++;
                if (!s_file.Value.Entries.Contains(m.GetDocumentationCommentId()!)) missing.Add(m.GetDocumentationCommentId()!);
            }
        Assert.AreEqual(14 * 3, count, "three methods on each of 13 integer types and on INumberBase<T> (char has none: only the interface reaches it)");
        CollectionAssert.AreEqual(Array.Empty<string>(), missing, "not banned, but should be: regenerate BannedSymbols.txt");

        // the same names on the floating-point types convert to a float: allowed
        Assert.IsFalse(s_file.Value.Entries.Any(e => e.StartsWith("M:System.Double.Create") || e.StartsWith("M:System.Single.Create") || e.StartsWith("M:System.Half.Create")));
    }

    // ---- T0.4c: the platform-intrinsics namespaces and the Vector ConvertTo family ----

    [TestMethod]
    public void EveryPlatformIntrinsicsNamespaceIsBannedAndThePortableOnesAreNot()
    {
        var intrinsics = s_compilation.Value.GlobalNamespace.GetNamespaceMembers().Single(n => n.Name == "System").GetNamespaceMembers().Single(n => n.Name == "Runtime")
            .GetNamespaceMembers().Single(n => n.Name == "Intrinsics");
        var children = intrinsics.GetNamespaceMembers().Select(n => n.Name).ToArray();
        CollectionAssert.IsSubsetOf(new[] { "X86", "Arm", "Wasm" }, children, "the three namespaces the card names must exist");

        var missing = children.Select(n => "N:System.Runtime.Intrinsics." + n).Where(id => !s_file.Value.Entries.Contains(id)).ToArray();
        CollectionAssert.AreEqual(Array.Empty<string>(), missing, "a namespace of the runtime is not banned: regenerate BannedSymbols.txt (or decide it is portable)");

        // the portable API lives in System.Runtime.Intrinsics itself: not banned, as a namespace or as a type
        Assert.IsFalse(s_file.Value.Entries.Contains("N:System.Runtime.Intrinsics"), "banning the parent namespace would ban Vector128<T>");
        Assert.IsFalse(s_file.Value.Entries.Any(e => e.StartsWith("T:System.Runtime.Intrinsics.Vector") || e.StartsWith("T:System.Runtime.Intrinsics.ISimdVector")), "Vector64/128/256/512<T> are portable types");
    }

    [TestMethod]
    public void EveryConvertToIntegerAndDecimalToNumberStaticMethodIsBanned()
    {
        string[] decimalNames = ["ToByte", "ToSByte", "ToInt16", "ToUInt16", "ToInt32", "ToUInt32", "ToInt64", "ToUInt64", "ToDouble", "ToSingle"];
        var missing = new List<string>();
        int count = 0;
        foreach (var type in new[] { "System.Double", "System.Single", "System.Half", "System.Decimal" })
            foreach (var m in PublicStaticMethods(type).Where(m => m.Name is "ConvertToInteger" or "ConvertToIntegerNative" || (type == "System.Decimal" && decimalNames.Contains(m.Name))))
            {
                count++;
                if (!s_file.Value.Entries.Contains(m.GetDocumentationCommentId()!)) missing.Add(m.GetDocumentationCommentId()!);
            }
        Assert.AreEqual(4 * 2 + 10, count, "ConvertToInteger and ConvertToIntegerNative on four types, and ten decimal.ToXxx");
        CollectionAssert.AreEqual(Array.Empty<string>(), missing, "not banned, but should be: regenerate BannedSymbols.txt");
    }

    [TestMethod]
    public void EveryVectorConvertToIntegerOverloadIsBannedAndTheOnesToFloatAreNot()
    {
        string[] banned = ["ConvertToInt32", "ConvertToInt64", "ConvertToUInt32", "ConvertToUInt64"];
        var missing = new List<string>();
        var wronglyBanned = new List<string>();
        int count = 0;
        foreach (var type in new[] { "System.Runtime.Intrinsics.Vector64", "System.Runtime.Intrinsics.Vector128", "System.Runtime.Intrinsics.Vector256", "System.Runtime.Intrinsics.Vector512" })
            foreach (var m in PublicStaticMethods(type).Where(m => m.Name.StartsWith("ConvertTo", StringComparison.Ordinal)))
            {
                var id = m.GetDocumentationCommentId()!;
                bool expected = banned.Contains(m.Name) || banned.Select(b => b + "Native").Contains(m.Name);
                if (expected) count++;
                if (expected && !s_file.Value.Entries.Contains(id)) missing.Add(id);
                if (!expected && s_file.Value.Entries.Contains(id)) wronglyBanned.Add(id);
            }
        Assert.AreEqual(4 * 8, count, "eight ConvertToInt32/Int64/UInt32/UInt64 (and Native) members on each of Vector64, 128, 256 and 512");
        CollectionAssert.AreEqual(Array.Empty<string>(), missing, "not banned, but should be: regenerate BannedSymbols.txt");
        CollectionAssert.AreEqual(Array.Empty<string>(), wronglyBanned, "banned, but it converts an integer to a float (IEEE-defined)");
    }

    [TestMethod]
    [DataRow("var x = Math.Abs(d);")]
    [DataRow("var x = Math.Sqrt(d);")]
    [DataRow("var x = Math.Floor(d);")]
    [DataRow("var x = Math.Ceiling(d);")]
    [DataRow("var x = Math.Truncate(d);")]
    [DataRow("var x = Math.CopySign(d, -1.0);")]
    [DataRow("var x = Math.Min(d, 1.0) + Math.Max(d, 1.0);")]
    [DataRow("var x = MathF.Sqrt(f) + MathF.Abs(f) + MathF.Min(f, 1f);")]
    [DataRow("var x = Math.Max(1, 2) + Math.Abs(-3) + Math.Min(4L, 5L);")]
    [DataRow("var x = Math.PI + Math.E;")]
    [DataRow("var x = Vector128.Create(1f) + Vector128.Create(2f);")]
    [DataRow("var x = Vector128.Floor(vd) + Vector128.Sqrt(vd);")]
    [DataRow("var x = double.Sqrt(d) + double.Abs(d);")]
    // T0.4b: the neighbours of the new bans stay allowed
    [DataRow("var x = Math.Truncate(d) + Math.Floor(d) + Math.Ceiling(d) + Math.CopySign(d, -1.0);")]
    [DataRow("var x = MathF.Truncate(f) + MathF.Floor(f);")]
    [DataRow("var x = Vector128.Add(v, v) + Vector128.Multiply(v, v) + Vector128.Subtract(v, v);")]
    [DataRow("var x = Vector128.ConditionalSelect(Vector128.GreaterThan(v, v), v, v);")]
    [DataRow("var x = Vector128.Multiply(vd, vd) + vd;")]
    [DataRow("var x = Convert.ToDouble(5) + Convert.ToDouble(5L) + Convert.ToDouble(f) + Convert.ToDouble(d);")]
    [DataRow("var x = Convert.ToSingle(d) + Convert.ToSingle(5);")]
    [DataRow("var x = Convert.ToInt32(\"12\") + Convert.ToInt32(5L) + Convert.ToInt32(true) + Convert.ToInt32('a');")]
    [DataRow("var x = Convert.ToString(d) + Convert.ToString(5) + Convert.ToHexString(new byte[1]);")]
    [DataRow("var x = double.CreateTruncating(5) + double.CreateSaturating(5L) + float.CreateChecked(5) + double.CreateTruncating(f);")]
    [DataRow("var x = int.Parse(\"3\") + int.MaxValue + int.Max(1, 2) + int.Abs(-1);")]
    [DataRow("var x = decimal.Add(1m, 2m) + decimal.Negate(1m) + decimal.Parse(\"1\");")]
    [DataRow("var x = double.IsNaN(d) || double.IsInfinity(d) || float.IsNaN(f) || Half.IsNaN(Half.One);")]
    // T0.4c: the portable vector API stays allowed, including the integer-to-float conversions (IEEE-defined) and the widening and narrowing forms
    [DataRow("var x = Vector128.ConvertToDouble(vl);")]
    [DataRow("var x = Vector128.ConvertToSingle(vi);")]
    [DataRow("var x = Vector256.ConvertToDouble(Vector256.Create(1L)); var y = Vector512.ConvertToSingle(Vector512.Create(1));")]
    [DataRow("var x = Vector128.WidenLower(v) + Vector128.WidenUpper(v);")]
    [DataRow("var x = Vector128.Narrow(vd, vd);")]
    [DataRow("var x = Vector128.IsHardwareAccelerated || Vector256.IsHardwareAccelerated || Vector512.IsHardwareAccelerated || Vector64.IsHardwareAccelerated;")]
    [DataRow("var x = Vector128.Create(1.0).AsInt64() + Vector128.CreateScalarUnsafe(d).AsInt64();")]
    [DataRow("var x = Vector128.LoadUnsafe(ref a[0]) + Vector128.Multiply(vd, vd) + Vector128.Min(vd, vd) + Vector128.Max(vd, vd) + Vector128.Abs(vd) + Vector128.Sqrt(vd);")]
    [DataRow("var x = Vector128.ShiftLeft(vi, 2) + Vector128.ShiftRightLogical(vi, 2);")]
    [DataRow("var x = Vector256.Add(Vector256.Create(1f), Vector256.Create(2f)); var y = Vector512.Add(Vector512.Create(1f), Vector512.Create(2f));")]
    [DataRow("var x = Vector128.Floor(vd) + Vector128.Ceiling(vd) + Vector128.Truncate(vd);")]
    public async Task BanApiAllowsTheAllowedCalls(string body)
    {
        var messages = await Rs0030Async(body);

        CollectionAssert.AreEqual(Array.Empty<string>(), messages);
    }
